    "property_id": "PROP-0000-create-inv-005",
    "text": "attendance.attendances type column must be constrained to valid values ('in', 'out').",
    "type": "invariant",
    "assertion": "forall a in attendances: a.type IN ('in', 'out')",
    "severity": "MEDIUM",
