37	    INTO v_display_name
38	    FROM auth.users au WHERE au.id = v_user_id;
39	  END IF;
40	
41	  -- 最新出退勤取得
42	  SELECT a.type INTO v_last_type
43	  FROM attendance.attendances a WHERE a.user_id = v_user_id
44	  ORDER BY a.timestamp DESC LIMIT 1;
45	
46	  v_new_type := CASE WHEN v_last_type = 'in' THEN 'out' ELSE 'in' END;
47	
48	  -- 出退勤記録挿入
49	  INSERT INTO attendance.attendances (user_id, card_id, type, timestamp, date)
50	  VALUES (v_user_id, p_card_id, v_new_type, v_now, v_date);
51	
52	  RETURN json_build_object(
53	    'success', true,
54	    'message', CASE WHEN v_new_type = 'in' THEN '出勤しました' ELSE '退勤しました' END,
55	    'user', json_build_object('display_name', v_display_name, 'discord_uid', v_discord_uid),
56	    'type', v_new_type
57	  );
58	EXCEPTION WHEN OTHERS THEN
59	  RETURN json_build_object('success', false, 'message', '打刻処理中にエラーが発生しました: ' || SQLERRM, 'user', null, 'type', null);
